function builderDeliveryMessage( submissionId: string, value: unknown, attachments: readonly BuilderDeliveryAttachment[] = [], ): Parameters<SendFn>[0] { const message = recordOf(value); const inputResponse = recordOf(message.inputResponse); const requestId = textOf(inputResponse.requestId); const optionId = textOf(inputResponse.optionId); const responseText = textOf(inputResponse.text); if (requestId && (optionId || responseText)) { return { inputResponses: [ { requestId, ...(optionId ? { optionId } : { text: responseText }), }, ], }; } const text = typeof message.text === "string" ? message.text : ""; const resources = Array.isArray(message.resources) ? message.resources : []; const context = [ `Submission id: ${submissionId}`, resources.length > 0 ? `Tagged resources: ${resources.map(resourceLabel).filter(Boolean).join(", ")}` : null, ] .filter(Boolean) .join("
"); const parts: Array<Record<string, unknown>> = [ { type: "text", text: `${context}

${text}` }, ]; for (const attachment of attachments) { parts.push({ type: "file", data: attachment.content, mediaType: attachment.mediaType, filename: attachment.name, }); } return parts as Parameters<SendFn>[0]; }

async function companyPreamble( companyId: string, opened: Opened, ): Promise<Preamble> { const company = await db.company.findUnique({ where: { id: companyId }, select: { name: true, domain: true, industry: true, description: true, contacts: { orderBy: [{ lastActivityAt: "desc" }, { createdAt: "asc" }], take: 12, select: { id: true, firstName: true, lastName: true, title: true }, }, deals: { orderBy: [{ lastActivityAt: "desc" }, { createdAt: "desc" }], take: 8, select: { id: true, name: true, stage: true }, }, _count: { select: { contacts: true } }, }, }); if (!company) { return { markdown: await closing(), focus: { companyId } }; } const people = company.contacts .map((person) => { const name = [person.firstName, person.lastName] .filter(Boolean) .join(" "); return `- ${name}${person.title ? ` — ${person.title}` : ""} \`${person.id}\``; }) .join("
"); const more = company._count.contacts > company.contacts.length ? `
- …and ${company._count.contacts - company.contacts.length} more; \`read_company_history\` lists them all.` : ""; const deals = company.deals .map((deal) => `${deal.name} (${deal.stage}) \`${deal.id}\``) .join("; "); const markdown = [ "## This session", "", `You are working on **${company.name}**${ company.domain ? ` (${company.domain})` : "" }${company.industry ? `, ${company.industry}` : ""} — company id \`${companyId}\`.`, "", opening( opened, "what this company does, who we know there, or what has changed recently", ), "", people ? `### Who we know there (${company._count.contacts})

${people}${more}

Those are contact ids. Use them directly — with \`read_crm_history\`, \`identify_contact\` or \`record_fact\`. Never ask a rep which contact they mean without naming these first.` : "We have no contacts on file here yet.", "", deals ? `Deals: ${deals}.` : "There are no deals here.", company.description ? "There is already a description on the record." : "There is no description on the record yet.", "", "Start with `read_company_history` on this company id — it returns the people, the deals, the correspondence and the notes in one free call.", "", await closing(), ] .filter(Boolean) .join("
"); return { markdown, focus: { companyId } }; }

