def dispatch_command(text): """Analyse une commande / et retourne un dict {ok, output} ou None si non gérée.""" text = text.strip() if not text.startswith("/"): return None parts = text.split(None, 2) cmd = parts[0].lower() args = parts[1] if len(parts) > 1 else "" rest = parts[2] if len(parts) > 2 else "" if cmd == "/help": lines = [ "### 📋 Commandes disponibles", "", "**Skills natifs :**", "- `/fs read <fichier>` — Lit un fichier", "- `/fs write <fichier> <contenu>` — Écrit un fichier", "- `/fs delete <chemin>` — Supprime un fichier ou dossier", "- `/fs replace <fichier> <ancien> >>> <nouveau>` — Remplace du texte", "- `/fs list <dossier>` — Liste le contenu", "- `/fs mkdir <dossier>` — Crée un dossier", "- `/code <description>` — Génère du code", "- `/mem <texte>` — Sauvegarde en mémoire", "- `/web <requête>` — Recherche web", "- `/img <description>` — Génère une image", "", "**Commandes UI :**", "- `/help` — Cette aide", "- `/new` — Nouvelle conversation", "- `/skills` — Liste les skills (onglet Compétences)", "- `/memory <requête>` — Recherche mémoire vectorielle", ] return {"ok": True, "output": "
".join(lines)} if cmd == "/fs": tokens = args.split(None, 1) action = tokens[0].lower() if tokens else "" path_arg = tokens[1] if len(tokens) > 1 else "" target, err = _resolve_path(path_arg) if err: return {"ok": False, "output": "❌ " + err} try: if action == "read": if not os.path.isfile(target): return {"ok": False, "output": f"❌ Fichier introuvable: {path_arg}"} with open(target, "r", encoding="utf-8", errors="ignore") as f: return {"ok": True, "output": f"📄 **{path_arg}**
```
{f.read()}
```"} elif action == "write": os.makedirs(os.path.dirname(target), exist_ok=True) with open(target, "w", encoding="utf-8") as f: f.write(rest) return {"ok": True, "output": f"✅ Fichier écrit: `{path_arg}`"} elif action == "delete": if os.path.isfile(target): os.remove(target) return {"ok": True, "output": f"🗑️ Fichier supprimé: `{path_arg}`"} elif os.path.isdir(target): shutil.rmtree(target) return {"ok": True, "output": f"🗑️ Dossier supprimé: `{path_arg}`"} return {"ok": False, "output": f"❌ Introuvable: {path_arg}"} elif action == "replace": if not os.path.isfile(target): return {"ok": False, "output": f"❌ Fichier introuvable: {path_arg}"} if " >>> " in rest: old, new = rest.split(" >>> ", 1) else: return {"ok": False, "output": "❌ Format: `/fs replace fichier.py ancien >>> nouveau`"} with open(target, "r", encoding="utf-8", errors="ignore") as f: content = f.read() if old not in content: return {"ok": False, "output": f"❌ Texte à remplacer introuvable dans `{path_arg}`"} new_content = content.replace(old, new, 1) with open(target, "w", encoding="utf-8") as f: f.write(new_content) return {"ok": True, "output": f"🔄 Remplacement effectué dans `{path_arg}`"} elif action == "list": if not os.path.isdir(target): return {"ok": False, "output": f"❌ Dossier introuvable: {path_arg}"} items = [] for entry in os.listdir(target): full = os.path.join(target, entry) typ = "📁" if os.path.isdir(full) else "📄" size = os.path.getsize(full) if os.path.isfile(full) else "-" items.append(f"{typ} {entry} ({size} bytes)") return {"ok": True, "output": f"📂 **{path_arg}**
" + ("
".join(items) if items else "(vide)")} elif action == "mkdir": os.makedirs(target, exist_ok=True) return {"ok": True, "output": f"📁 Dossier créé: `{path_arg}`"} else: return {"ok": False, "output": f"❌ Action inconnue: `{action}`. Utilise: read, write, delete, replace, list, mkdir"} except PermissionError: return {"ok": False, "output": f"❌ Permission refusée: {path_arg}"} except Exception as e: return {"ok": False, "output": f"❌ Erreur: {e}"} if cmd == "/code": if not args: return {"ok": False, "output": "❌ Usage: `/code <description du code à générer>`"} return { "ok": True, "output": f"💻 **Génération de code**

